<?php
require __DIR__.'/src/commerce.php';require_admin();if(!can_manage('content')){http_response_code(403);exit('غير مصرح');}
$id=filter_input(INPUT_GET,'item',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('العنصر غير صحيح');}
$q=db()->prepare('SELECT id,title FROM items WHERE id=?');$q->execute([$id]);$item=$q->fetch();if(!$item){http_response_code(404);exit('غير موجود');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='add'){$url=trim((string)($_POST['image_url']??''));$scheme=strtolower((string)parse_url($url,PHP_URL_SCHEME));if(mb_strlen($url)>2048||!filter_var($url,FILTER_VALIDATE_URL)||!in_array($scheme,['https','http'],true))$error='رابط الصورة غير صحيح';else{$q=db()->prepare('INSERT INTO item_images(item_id,image_url,sort_order) VALUES(?,?,?)');$q->execute([$id,$url,(int)($_POST['sort_order']??0)]);log_action('admin',(int)$_SESSION['admin_id'],'gallery_image_added','item',$id);redirect('admin-gallery.php?item='.$id);}}
elseif($action==='delete'){$q=db()->prepare('DELETE FROM item_images WHERE id=? AND item_id=?');$q->execute([(int)($_POST['image_id']??0),$id]);log_action('admin',(int)$_SESSION['admin_id'],'gallery_image_deleted','item',$id);redirect('admin-gallery.php?item='.$id);}}
$q=db()->prepare('SELECT * FROM item_images WHERE item_id=? ORDER BY sort_order,id');$q->execute([$id]);$images=$q->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=4"><title>معرض الصور | نَسَق</title></head><body><header class="site-header"><nav class="wrap site-nav"><a class="brand" href="admin.php"><span class="brand-mark">ن</span>نَسَق</a><a class="btn secondary" href="admin.php">لوحة التحكم</a></nav></header><main class="wrap"><section class="pagehead"><h1>معرض صور: <?=e($item['title'])?></h1><p>أضف روابط صور خارجية آمنة. لا يتم رفع الصور إلى الاستضافة.</p></section><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form class="form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><label>رابط الصورة<input name="image_url" type="url" maxlength="2048" required placeholder="https://example.com/photo.jpg"></label><label>الترتيب<input name="sort_order" type="number" value="0"></label><button class="btn">إضافة الصورة</button></form><div class="gallery"><?php foreach($images as $img):?><div class="panel"><img src="<?=e($img['image_url'])?>" alt="صورة المعرض" loading="lazy"><form method="post" data-confirm="حذف الصورة من المعرض؟"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="image_id" value="<?=(int)$img['id']?>"><button class="btn secondary">حذف</button></form></div><?php endforeach;?></div></main><script src="assets/app.js?v=4" defer></script></body></html>